'use strict';
const KEY='rattibha-family-v1', DAYS=['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
const $=id=>document.getElementById(id);
function sunday(value=new Date()){const d=new Date(value);d.setDate(d.getDate()-d.getDay());return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function fresh(){return {version:1,week:sunday(),tasks:[],meals:Array(7).fill(''),shopping:[],priority:'',routines:[{title:'صباح مرتب',items:['فطور وماء','تأكد من الحقيبة','خروج في الوقت المتفق عليه'],done:[]},{title:'بعد المدرسة',items:['راحة ووجبة خفيفة','مراجعة الواجبات','وقت للحركة واللعب'],done:[]},{title:'نجهّز لبكرة',items:['الحقيبة والملابس جاهزة','مراجعة موعد الغد','وقت نوم متفق عليه'],done:[]}]};}
function validate(s){const str=(x,n)=>typeof x==='string'&&x.length<=n; const validDate=x=>/^\d{4}-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(Date.parse(x));return s&&s.version===1&&str(s.week,10)&&validDate(s.week)&&str(s.priority,500)&&Array.isArray(s.meals)&&s.meals.length===7&&s.meals.every(x=>str(x,100))&&Array.isArray(s.tasks)&&s.tasks.length<=300&&s.tasks.every(t=>t&&str(t.id,80)&&Number.isInteger(t.day)&&t.day>=0&&t.day<7&&str(t.text,140)&&str(t.owner,40)&&str(t.time,5)&&(!t.time||/^([01]\d|2[0-3]):[0-5]\d$/.test(t.time))&&typeof t.done==='boolean')&&Array.isArray(s.shopping)&&s.shopping.length<=300&&s.shopping.every(t=>t&&str(t.id,80)&&str(t.text,100)&&typeof t.done==='boolean')&&Array.isArray(s.routines)&&s.routines.length===3&&s.routines.every(r=>r&&str(r.title,50)&&Array.isArray(r.items)&&r.items.length<=15&&r.items.every(x=>str(x,140))&&Array.isArray(r.done)&&r.done.every(x=>Number.isInteger(x)&&x>=0&&x<r.items.length));}
let state=fresh(),storageWarning=false;try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(validate(parsed))state=parsed;else storageWarning=true;}}catch{storageWarning=true;}
function say(s){$('status').textContent=s;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));say('تم الحفظ في هذا المتصفح.');}catch{say('تعذّر الحفظ في المتصفح. نزّل نسخة احتياطية قبل إغلاق الصفحة.');}progress();}
function progress(){const total=state.tasks.length,done=state.tasks.filter(t=>t.done).length;$('progress').textContent=`${done.toLocaleString('ar-SA')} من ${total.toLocaleString('ar-SA')} مهام مكتملة`;$('meter').style.width=(total?done/total*100:0)+'%';}
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function line(t,collection){const li=node('li',undefined,'taskline'+(t.done?' done':'')),label=node('label'),check=node('input'),span=node('span'),txt=node('span',t.text,'tasktext');check.type='checkbox';check.checked=t.done;check.addEventListener('change',()=>{t.done=check.checked;li.classList.toggle('done',t.done);save();});span.append(txt);if(collection==='tasks')span.append(node('small',[t.owner,t.time].filter(Boolean).join(' · ')));label.append(check,span);const del=node('button','×','delete');del.type='button';del.setAttribute('aria-label','حذف '+t.text);del.addEventListener('click',()=>{state[collection]=state[collection].filter(x=>x.id!==t.id);save();render();});li.append(label,del);return li;}
function render(){ $('week').value=state.week;$('priority').value=state.priority;$('days').replaceChildren();DAYS.forEach((day,i)=>{const card=node('article',undefined,'day'),h=node('h3',day),d=new Date(state.week+'T12:00:00');d.setDate(d.getDate()+i);h.append(node('small',d.toLocaleDateString('ar-SA',{calendar:'gregory',month:'numeric',day:'numeric'})));const ul=node('ul'),tasks=state.tasks.filter(t=>t.day===i).sort((a,b)=>a.time.localeCompare(b.time));if(!tasks.length)ul.append(node('li','مساحة ليومك','empty'));tasks.forEach(t=>ul.append(line(t,'tasks')));const label=node('label','وجبة اليوم','meal'),input=node('input');input.value=state.meals[i];input.maxLength=100;input.placeholder='وش الغداء؟';input.addEventListener('input',()=>{state.meals[i]=input.value;save();});label.append(input);card.append(h,ul,label);$('days').append(card);});$('shoplist').replaceChildren(...state.shopping.map(t=>line(t,'shopping')));$('shopempty').hidden=state.shopping.length>0;renderRoutines();progress();}
function renderRoutines(){$('routinecards').replaceChildren();state.routines.forEach(r=>{const card=node('article',undefined,'routine'),checks=node('div',undefined,'routinechecks');r.items.forEach((text,i)=>{const label=node('label'),check=node('input');check.type='checkbox';check.checked=r.done.includes(i);check.addEventListener('change',()=>{r.done=check.checked?[...new Set([...r.done,i])]:r.done.filter(x=>x!==i);save();});label.append(check,node('span',text));checks.append(label);});const details=node('details'),summary=node('summary','تعديل الخطوات'),label=node('label','كل خطوة في سطر، حتى ١٥ خطوة'),ta=node('textarea');ta.value=r.items.join('\n');ta.maxLength=2100;ta.addEventListener('change',()=>{r.items=ta.value.split('\n').map(x=>x.trim().slice(0,140)).filter(Boolean).slice(0,15);r.done=[];save();renderRoutines();});label.append(ta);details.append(summary,label);card.append(node('h3',r.title),checks,details);$('routinecards').append(card);});}
DAYS.forEach((d,i)=>{const o=node('option',d);o.value=i;$('day').append(o);});
$('week').addEventListener('change',()=>{if(!$('week').value){$('week').value=state.week;return;}state.week=sunday(new Date($('week').value+'T12:00:00'));save();render();say('تم تغيير تاريخ الخطة الحالية؛ لم تُحذف المهام.');});
$('priority').addEventListener('input',()=>{state.priority=$('priority').value;save();});
$('taskform').addEventListener('submit',e=>{e.preventDefault();const text=$('task').value.trim();if(!text)return;if(state.tasks.length>=300){say('وصلت الخطة إلى ٣٠٠ مهمة.');return;}state.tasks.push({id:crypto.randomUUID(),day:Number($('day').value),text,owner:$('owner').value.trim(),time:$('time').value,done:false});$('task').value='';save();render();$('task').focus();});
$('shopform').addEventListener('submit',e=>{e.preventDefault();const text=$('item').value.trim();if(!text)return;if(state.shopping.length>=300){say('وصلت القائمة إلى ٣٠٠ صنف.');return;}state.shopping.push({id:crypto.randomUUID(),text,done:false});$('item').value='';save();render();$('item').focus();});
const tabs=[...document.querySelectorAll('[data-tab]')];function activate(btn){tabs.forEach(b=>{const active=b===btn;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;$(b.dataset.tab).hidden=!active;});}tabs.forEach((b,i)=>{b.tabIndex=i? -1:0;b.addEventListener('click',()=>activate(b));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowLeft'?1:-1)+tabs.length)%tabs.length;activate(tabs[index]);tabs[index].focus();});});
$('print').addEventListener('click',()=>window.print());
$('reset-routines').addEventListener('click',()=>{state.routines.forEach(r=>r.done=[]);save();renderRoutines();});
$('export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download='rattibha-'+state.week+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);say('تم تجهيز النسخة الاحتياطية للتنزيل.');});
$('import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>250000)throw Error();const s=JSON.parse(await file.text());if(!validate(s))throw Error();if(!confirm('استبدال الخطة الحالية بالخطة المستوردة؟'))return;state=s;save();render();}catch{say('الملف غير صالح. اختر نسخة JSON مصدّرة من رتّبها.');}finally{e.target.value='';}});
$('reset').addEventListener('click',()=>{if(confirm('مسح الخطة الحالية بالكامل؟ نزّل نسخة احتياطية أولًا إذا احتجتها.')){state=fresh();save();render();}});render();if(storageWarning)say('تعذّر استرجاع الخطة المحفوظة. يمكنك استيراد نسخة احتياطية.');
